shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --crimson: #8f241e;
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283e54;
    --serif-en: 'Playfair Display', Georgia, serif;
    --body-en: 'Lora', Georgia, serif;
    --serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--serif-cn);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--body-en);
    line-height: 1.78;
  }

  /* Reading Progress Bar */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: transparent;
    z-index: 1000;
  }
  .progress-fill {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 900;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.75rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }
  .wsj-mark {
    font-family: var(--serif-en);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }
  .brand-divider {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }
  .section-tag {
    font-family: var(--mono);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }
  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--sans);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    padding: 0.28rem 0.75rem;
    border-radius: 999px;
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .page-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0 1.5rem 5rem;
  }

  /* Hero Header */
  .hero-header {
    padding: 3.5rem 0 2.5rem;
    border-bottom: 2px solid var(--ink);
    margin-bottom: 2.75rem;
  }
  .hero-kicker-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.1rem;
    flex-wrap: wrap;
  }
  .kicker-pill {
    font-family: var(--mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: var(--ink);
    color: var(--paper);
    padding: 0.22rem 0.6rem;
  }
  .kicker-meta {
    font-family: var(--mono);
    font-size: 0.75rem;
    color: var(--muted);
    letter-spacing: 0.05em;
  }
  .article-title {
    font-family: var(--serif-cn);
    font-weight: 700;
    font-size: clamp(2.1rem, 4.3vw, 3.35rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.25rem;
    max-width: 960px;
  }
  :host([lang="en"]) .article-title {
    font-family: var(--serif-en);
    font-weight: 800;
    line-height: 1.12;
  }
  .article-dek {
    font-family: var(--sans);
    font-size: 1.12rem;
    line-height: 1.65;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 1.75rem;
    font-weight: 400;
  }
  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.2rem;
    border-top: 1px solid var(--line);
    font-family: var(--sans);
    font-size: 0.82rem;
    color: var(--muted);
  }
  .byline-authors strong {
    color: var(--ink);
    font-weight: 700;
    letter-spacing: 0.03em;
  }
  .byline-date {
    font-family: var(--mono);
    font-size: 0.78rem;
  }

  /* Quick Key Numbers Strip */
  .stat-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-bottom: 3rem;
  }
  .stat-cell {
    background: var(--paper-card);
    padding: 1.25rem 1.35rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  .stat-num {
    font-family: var(--mono);
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.15;
    margin-bottom: 0.35rem;
  }
  .stat-num .accent-unit {
    color: var(--accent);
    font-size: 1.05rem;
  }
  .stat-label {
    font-family: var(--sans);
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--body);
    margin-bottom: 0.2rem;
  }
  .stat-sub {
    font-family: var(--sans);
    font-size: 0.72rem;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Asymmetric Editorial Grid */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(280px, 4.2fr);
    gap: 3.25rem;
    align-items: start;
    margin-bottom: 3rem;
  }
  .prose-col {
    min-width: 0;
  }
  .rail-col {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.45rem;
    letter-spacing: 0.01em;
  }
  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
  }
  .prose-lead {
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.65rem;
    line-height: 1.75;
  }

  mark.ed-hl {
    background: var(--accent-soft);
    color: var(--ink);
    padding: 0.06em 0.28em;
    border-bottom: 1.5px solid var(--accent);
    font-weight: 600;
  }

  /* Section Divider Headers */
  .chapter-divider {
    margin: 3.25rem 0 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--ink);
    display: flex;
    align-items: baseline;
    gap: 1rem;
  }
  .chapter-num {
    font-family: var(--mono);
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.1em;
    text-transform: uppercase;
    flex-shrink: 0;
  }
  .chapter-title {
    font-family: var(--serif-cn);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
  }
  :host([lang="en"]) .chapter-title {
    font-family: var(--serif-en);
  }

  /* Dossier & Callout Cards */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.5rem;
  }
  .dossier-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.85rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid var(--line);
  }
  .dossier-kicker {
    font-family: var(--mono);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .dossier-badge {
    font-family: var(--mono);
    font-size: 0.68rem;
    color: var(--muted);
    background: var(--paper-deep);
    padding: 0.15rem 0.45rem;
  }
  .dossier-body {
    font-family: var(--sans);
    font-size: 0.88rem;
    line-height: 1.7;
    color: var(--body);
  }

  /* Pull Quote Card */
  .pull-quote {
    background: var(--paper-card);
    border-left: 4px solid var(--accent);
    padding: 1.4rem 1.5rem;
    margin: 0;
  }
  .pull-quote .quote-text {
    font-family: var(--serif-cn);
    font-size: 1.12rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }
  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--serif-en);
    font-style: italic;
  }
  .pull-quote .quote-attrib {
    font-family: var(--mono);
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Incident Forensic Box */
  .forensic-card {
    background: var(--navy-bg);
    color: #f3efe6;
    padding: 1.65rem;
    border-top: 3px solid var(--accent);
  }
  .forensic-title {
    font-family: var(--mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #e29356;
    margin-bottom: 1rem;
    display: block;
  }
  .forensic-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.9rem;
  }
  .forensic-item {
    border-bottom: 1px solid var(--navy-line);
    padding-bottom: 0.75rem;
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 1rem;
  }
  .forensic-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
  .forensic-key {
    font-family: var(--sans);
    font-size: 0.8rem;
    color: #a9b7c6;
  }
  .forensic-val {
    font-family: var(--mono);
    font-size: 0.86rem;
    font-weight: 600;
    color: #ffffff;
    text-align: right;
  }

  /* SVG Diagram Container */
  .viz-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.75rem 1.75rem 1.4rem;
    margin: 2.5rem 0 3rem;
  }
  .viz-header {
    margin-bottom: 1.25rem;
  }
  .viz-kicker {
    font-family: var(--mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.09em;
    text-transform: uppercase;
    margin-bottom: 0.3rem;
  }
  .viz-title {
    font-family: var(--serif-cn);
    font-size: 1.28rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }
  :host([lang="en"]) .viz-title {
    font-family: var(--serif-en);
  }
  .viz-subtitle {
    font-family: var(--sans);
    font-size: 0.84rem;
    color: var(--muted);
    line-height: 1.5;
  }
  .viz-svg-wrap {
    width: 100%;
    overflow: hidden;
  }
  .viz-svg-wrap svg {
    width: 100%;
    height: auto;
    display: block;
  }
  .viz-footnote {
    margin-top: 1rem;
    padding-top: 0.75rem;
    border-top: 1px solid var(--line);
    font-family: var(--mono);
    font-size: 0.72rem;
    color: var(--muted);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Spectrum of Opposition Grid */
  .reaction-matrix {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
    margin: 2rem 0 2.75rem;
  }
  .reaction-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  .reaction-card.highlight-card {
    border-top: 3px solid var(--crimson);
  }
  .reaction-card.admin-card {
    border-top: 3px solid var(--navy-bg);
  }
  .reaction-card.church-card {
    border-top: 3px solid var(--accent);
  }
  .reaction-role {
    font-family: var(--mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.4rem;
  }
  .reaction-person {
    font-family: var(--sans);
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }

  /* Regulatory Paradox Closing Callout */
  .paradox-banner {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 2.25rem;
    border-left: 5px solid var(--accent);
    margin-top: 2rem;
  }
  .paradox-header {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    margin-bottom: 1rem;
  }
  .paradox-tag {
    font-family: var(--mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: var(--accent);
    color: #fff;
    padding: 0.2rem 0.55rem;
  }
  .paradox-title {
    font-family: var(--sans);
    font-size: 0.88rem;
    font-weight: 600;
    color: #cbd5e1;
  }
  .paradox-banner .prose-p {
    color: #f3efe6;
    margin-bottom: 1rem;
  }
  .paradox-banner .prose-p:last-child {
    margin-bottom: 0;
  }
  .paradox-banner mark.ed-hl {
    background: rgba(226, 147, 86, 0.25);
    color: #fff;
    border-bottom-color: #e29356;
  }

  /* Footer */
  .ed-footer {
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 2px solid var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 900px) {
    .stat-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .reaction-matrix {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 520px) {
    .masthead {
      padding: 0.65rem 1rem;
    }
    .page-shell {
      padding: 0 1rem 3.5rem;
    }
    .hero-header {
      padding: 2.2rem 0 1.75rem;
    }
    .stat-strip {
      grid-template-columns: 1fr;
    }
    .viz-panel {
      padding: 1.25rem 1rem;
    }
    .paradox-banner {
      padding: 1.5rem 1.25rem;
    }
  }
